import { AppData, DailyStats } from '../types';
import { INITIAL_PIN } from '../constants';

const STORAGE_KEY = 'mr_rider_wallet_data';

const createNewDay = (goal: number): DailyStats => ({
  date: new Date().toISOString().split('T')[0],
  earnings: 0,
  ownerShare: 0,
  fuel: 0,
  purchases: 0,
  goal: goal
});

export const getInitialData = (): AppData => {
  const stored = localStorage.getItem(STORAGE_KEY);
  if (stored) {
    const data = JSON.parse(stored) as AppData;
    // Check if we need a settlement (new day)
    const today = new Date().toISOString().split('T')[0];
    if (data.currentDay.date !== today) {
       // Automatic Settlement
       const net = data.currentDay.earnings - (data.currentDay.ownerShare + data.currentDay.fuel + data.currentDay.purchases);
       if (net > 0) {
         data.vault.push({ date: data.currentDay.date, amount: net });
       }
       data.currentDay = createNewDay(data.settings.dailyGoal);
       data.lastSettlementDate = today;
       saveData(data);
    }
    return data;
  }

  const defaultData: AppData = {
    currentDay: createNewDay(5000),
    vault: [],
    settings: {
      dailyGoal: 5000,
      vaultPin: INITIAL_PIN
    },
    lastSettlementDate: new Date().toISOString().split('T')[0]
  };
  saveData(defaultData);
  return defaultData;
};

export const saveData = (data: AppData) => {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
};

export const exportData = (data: AppData) => {
  const blob = new Blob([JSON.stringify(data)], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `rider_wallet_backup_${new Date().toISOString().split('T')[0]}.json`;
  a.click();
};

import React from 'react';

interface KeypadProps {
  onInput: (val: string) => void;
  onClear: () => void;
  onConfirm: () => void;
  title: string;
  value: string;
}

const Keypad: React.FC<KeypadProps> = ({ onInput, onClear, onConfirm, title, value }) => {
  const keys = ['1', '2', '3', '4', '5', '6', '7', '8', '9', 'C', '0', '✓'];

  return (
    <div className="bg-white p-6 rounded-t-3xl shadow-2xl fixed bottom-0 left-0 right-0 z-50">
      <div className="text-center mb-4">
        <h3 className="text-xl font-bold text-gray-800">{title}</h3>
        <div className="text-4xl font-black text-blue-600 mt-2 tracking-widest">
          {value || '0'} <span className="text-sm font-normal text-gray-500">أوقية</span>
        </div>
      </div>
      <div className="grid grid-cols-3 gap-3">
        {keys.map((key) => (
          <button
            key={key}
            onClick={() => {
              if (key === 'C') onClear();
              else if (key === '✓') onConfirm();
              else onInput(key);
            }}
            className={`
              h-16 flex items-center justify-center text-2xl font-bold rounded-xl active:scale-95 transition-transform
              ${key === 'C' ? 'bg-red-100 text-red-600' : key === '✓' ? 'bg-green-600 text-white' : 'bg-gray-100 text-gray-800'}
            `}
          >
            {key}
          </button>
        ))}
      </div>
    </div>
  );
};

export default Keypad;

import React, { useState, useEffect, useCallback } from 'react';
import { AppData, DailyStats } from './types';
import { getInitialData, saveData, exportData } from './services/storage';
import { Icons, CURRENCY } from './constants';
import Keypad from './components/Keypad';

const App: React.FC = () => {
  const [data, setData] = useState<AppData | null>(null);
  const [activeInput, setActiveInput] = useState<{ type: keyof DailyStats | 'pin' | 'goal', title: string } | null>(null);
  const [inputValue, setInputValue] = useState('');
  const [showVault, setShowVault] = useState(false);
  const [vaultUnlocked, setVaultUnlocked] = useState(false);
  const [showSettings, setShowSettings] = useState(false);

  useEffect(() => {
    setData(getInitialData());
  }, []);

  const handleUpdateValue = useCallback(() => {
    if (!data || !activeInput) return;

    const numValue = parseInt(inputValue) || 0;
    const newData = { ...data };

    if (activeInput.type === 'pin') {
       if (inputValue === data.settings.vaultPin) {
         setVaultUnlocked(true);
         setActiveInput(null);
         setInputValue('');
       } else {
         alert('رمز PIN غير صحيح');
         setInputValue('');
       }
       return;
    }

    if (activeInput.type === 'goal') {
      newData.settings.dailyGoal = numValue;
      newData.currentDay.goal = numValue;
    } else {
      // For earnings/expenses, we add to the existing daily total
      const field = activeInput.type as keyof DailyStats;
      (newData.currentDay[field] as number) += numValue;
    }

    setData(newData);
    saveData(newData);
    setActiveInput(null);
    setInputValue('');
  }, [data, activeInput, inputValue]);

  if (!data) return <div className="p-10 text-center font-bold">جاري التحميل...</div>;

  const netBalance = data.currentDay.earnings - (data.currentDay.ownerShare + data.currentDay.fuel + data.currentDay.purchases);
  const progress = Math.min((netBalance / data.currentDay.goal) * 100, 100);

  return (
    <div className="min-h-screen max-w-md mx-auto bg-white flex flex-col p-4 pb-24">
      {/* Header */}
      <div className="flex justify-between items-center mb-6">
        <button 
          onClick={() => setShowSettings(true)}
          className="p-3 bg-gray-100 rounded-full text-gray-800 border-2 border-gray-200"
        >
          <Icons.Settings />
        </button>
        <div className="text-center">
          <h1 className="text-2xl font-black text-gray-900">محفظة السائق</h1>
          <p className="text-gray-500 font-bold">{data.currentDay.date}</p>
        </div>
        <button 
          onClick={() => {
            setShowVault(true);
            setVaultUnlocked(false);
            setActiveInput({ type: 'pin', title: 'أدخل رمز PIN للخزنة' });
          }}
          className="p-3 bg-yellow-100 rounded-full text-yellow-700 border-2 border-yellow-200"
        >
          <Icons.Vault />
        </button>
      </div>

      {/* Goal Progress */}
      <div className="bg-[#FFFBEB] border-4 border-[#FBBF24] rounded-2xl p-6 mb-6 shadow-sm">
        <div className="flex justify-between items-end mb-2">
          <span className="text-lg font-black text-gray-800">الهدف اليومي: {data.currentDay.goal} {CURRENCY}</span>
          <span className="text-2xl font-black text-amber-600">{Math.round(progress)}%</span>
        </div>
        <div className="w-full bg-amber-200 rounded-full h-6 overflow-hidden border-2 border-amber-300">
          <div 
            className="bg-amber-500 h-full transition-all duration-500" 
            style={{ width: `${progress}%` }}
          />
        </div>
      </div>

      {/* Net Balance Display */}
      <div className="bg-blue-600 rounded-3xl p-8 text-white mb-8 shadow-xl border-b-8 border-blue-800">
        <p className="text-blue-100 font-bold mb-1 text-lg">الرصيد الصافي الحالي</p>
        <h2 className="text-5xl font-black tracking-tight">
          {netBalance.toLocaleString()} <span className="text-xl">{CURRENCY}</span>
        </h2>
      </div>

      {/* Action Grid */}
      <div className="grid grid-cols-2 gap-4 flex-grow">
        <ActionButton 
          label="الكسب" 
          icon={<Icons.Plus />} 
          color="bg-green-100" 
          textColor="text-green-800"
          borderColor="border-green-300"
          value={data.currentDay.earnings}
          onClick={() => setActiveInput({ type: 'earnings', title: 'إضافة مبلغ الكسب' })}
        />
        <ActionButton 
          label="نسبة المالك" 
          icon={<Icons.Minus />} 
          color="bg-red-100" 
          textColor="text-red-800"
          borderColor="border-red-300"
          value={data.currentDay.ownerShare}
          onClick={() => setActiveInput({ type: 'ownerShare', title: 'خصم نسبة المالك' })}
        />
        <ActionButton 
          label="الوقود" 
          icon={<Icons.Minus />} 
          color="bg-orange-100" 
          textColor="text-orange-800"
          borderColor="border-orange-300"
          value={data.currentDay.fuel}
          onClick={() => setActiveInput({ type: 'fuel', title: 'خصم مصاريف الوقود' })}
        />
        <ActionButton 
          label="مشتريات" 
          icon={<Icons.Minus />} 
          color="bg-purple-100" 
          textColor="text-purple-800"
          borderColor="border-purple-300"
          value={data.currentDay.purchases}
          onClick={() => setActiveInput({ type: 'purchases', title: 'خصم المشتريات اليومية' })}
        />
      </div>

      {/* Modals & Overlays */}
      {activeInput && (
        <div className="fixed inset-0 bg-black/50 z-40 backdrop-blur-sm" onClick={() => {
          if (activeInput.type !== 'pin') setActiveInput(null);
        }}>
          <div onClick={e => e.stopPropagation()}>
            <Keypad 
              title={activeInput.title}
              value={inputValue}
              onInput={(v) => setInputValue(prev => prev + v)}
              onClear={() => setInputValue('')}
              onConfirm={handleUpdateValue}
            />
          </div>
        </div>
      )}

      {showVault && vaultUnlocked && (
        <div className="fixed inset-0 bg-white z-50 overflow-y-auto p-6">
          <div className="flex justify-between items-center mb-6">
            <h2 className="text-3xl font-black text-gray-900">الخزنة (المدخرات)</h2>
            <button onClick={() => setShowVault(false)} className="text-gray-500 font-bold text-lg">إغلاق</button>
          </div>
          <div className="bg-yellow-50 border-4 border-yellow-200 rounded-2xl p-6 mb-6">
            <p className="text-yellow-800 font-bold mb-1">إجمالي الخزنة</p>
            <h3 className="text-4xl font-black text-yellow-600">
              {data.vault.reduce((acc, curr) => acc + curr.amount, 0).toLocaleString()} {CURRENCY}
            </h3>
          </div>
          <div className="space-y-4">
            <h4 className="font-black text-gray-500 border-b pb-2">سجل التحويلات اليومية</h4>
            {data.vault.length === 0 && <p className="text-center text-gray-400 py-10">لا توجد سجلات بعد</p>}
            {[...data.vault].reverse().map((entry, idx) => (
              <div key={idx} className="flex justify-between items-center p-4 bg-gray-50 rounded-xl border-2 border-gray-100">
                <span className="font-bold text-gray-600">{entry.date}</span>
                <span className="font-black text-green-700">+{entry.amount} {CURRENCY}</span>
              </div>
            ))}
          </div>
        </div>
      )}

      {showSettings && (
        <div className="fixed inset-0 bg-white z-50 p-6">
           <div className="flex justify-between items-center mb-10">
            <h2 className="text-3xl font-black text-gray-900">الإعدادات</h2>
            <button onClick={() => setShowSettings(false)} className="text-gray-500 font-bold text-lg">إغلاق</button>
          </div>

          <div className="space-y-8">
            <section>
              <h3 className="text-lg font-black mb-4 text-gray-800">الأمان والبيانات</h3>
              <div className="space-y-4">
                <button 
                  onClick={() => setActiveInput({ type: 'goal', title: 'تعديل الهدف اليومي' })}
                  className="w-full text-right p-4 bg-gray-100 rounded-xl font-bold flex justify-between items-center"
                >
                   <span>تعديل الهدف اليومي</span>
                   <span className="text-blue-600">{data.settings.dailyGoal} {CURRENCY}</span>
                </button>
                <button 
                   onClick={() => exportData(data)}
                   className="w-full text-right p-4 bg-blue-100 text-blue-800 rounded-xl font-bold border-2 border-blue-200"
                >
                  تصدير نسخة احتياطية (Backup)
                </button>
                <div className="p-4 bg-gray-50 border border-dashed border-gray-300 rounded-xl">
                  <p className="text-sm text-gray-500">ملاحظة: يتم تصفير العداد يومياً الساعة 12:00 ليلاً ونقل الصافي للخزنة تلقائياً.</p>
                </div>
              </div>
            </section>
          </div>
        </div>
      )}
    </div>
  );
};

interface ActionButtonProps {
  label: string;
  icon: React.ReactNode;
  color: string;
  textColor: string;
  borderColor: string;
  value: number;
  onClick: () => void;
}

const ActionButton: React.FC<ActionButtonProps> = ({ label, icon, color, textColor, borderColor, value, onClick }) => {
  return (
    <button 
      onClick={onClick}
      className={`${color} ${borderColor} border-4 rounded-3xl p-4 flex flex-col justify-between items-start h-36 active:scale-95 transition-transform shadow-sm`}
    >
      <div className={`${textColor} bg-white/50 p-2 rounded-lg`}>{icon}</div>
      <div className="text-right w-full">
        <p className={`${textColor} font-black text-lg`}>{label}</p>
        <p className={`${textColor} font-bold opacity-80 text-sm`}>{value.toLocaleString()} {CURRENCY}</p>
      </div>
    </button>
  );
};

export default App;

