            <div className="space-y-4">
              <h4 className="font-black text-gray-500 border-b-2 border-gray-200 pb-2">السجل التاريخي</h4>
              {data.vault.length === 0 && <div className="text-center text-gray-400 py-16 text-lg font-bold">الخزنة فارغة حالياً</div>}
              {[...data.vault].reverse().map((entry, idx) => (
                <div key={idx} className="flex justify-between items-center p-5 bg-white rounded-2xl border-2 border-gray-200 shadow-sm">
                  <span className="font-bold text-gray-500">{entry.date}</span>
                  <span className="font-black text-green-600 text-xl">+{entry.amount.toLocaleString()}</span>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {showSettings && (
        <div className="fixed inset-0 bg-[#F9FAFB] z-[70] p-6">
           <div className="flex justify-between items-center mb-10">
            <h2 className="text-3xl font-black text-gray-900">الإعدادات ⚙️</h2>
            <button onClick={() => setShowSettings(false)} className="p-2 bg-gray-200 rounded-xl font-black text-gray-700 px-4">إغلاق</button>
          </div>

          <div className="space-y-6">
            <div className="bg-white p-6 rounded-3xl border-2 border-gray-100 shadow-sm">
              <h3 className="text-lg font-black mb-4 text-gray-800">إدارة البيانات</h3>
              <div className="space-y-3">
                <button 
                   onClick={() => exportData(data)}
                   className="w-full text-right p-5 bg-blue-600 text-white rounded-2xl font-black text-lg shadow-lg border-b-4 border-blue-800 active:translate-y-1 active:border-b-0 transition-all"
                >
                  حفظ نسخة احتياطية (Export)
                </button>
                <div className="p-4 bg-orange-50 border-2 border-orange-200 rounded-2xl flex items-start gap-3">
                  <span className="text-2xl">ℹ️</span>
                  <p className="text-sm text-orange-900 font-bold leading-relaxed">
                    يتم ترحيل الأموال تلقائياً للخزنة يومياً عند الساعة 12:00 ليلاً. تأكد من إدخال جميع مبالغك قبل نهاية اليوم.
                  </p>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

